namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string Name { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]+$", ErrorMessage = "Student ID must be alphanumeric.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    List<Department> GetDepartments();
    Department? GetDepartment(int id);
    List<Course> GetCourses(string? search, int? departmentId);
    Course? GetCourse(int id);
    List<Course> GetFeaturedCourses();
    void SubmitEnrollmentRequest(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class InMemoryCatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public InMemoryCatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Description = "Exploration of numbers, structures, and abstract patterns." },
            new() { Id = 3, Name = "English", Description = "Literature, writing, and critical analysis of texts." },
            new() { Id = 4, Name = "Physics", Description = "Understanding the fundamental laws governing the universe." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, DepartmentId = 1, Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, object-oriented design, and basic data structures.", Credits = 4, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and has published extensively on programming pedagogy.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures including arrays, linked lists, trees, and graphs along with sorting and searching algorithms.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez specializes in algorithm design and has contributed to open-source compiler projects." },
            new() { Id = 3, DepartmentId = 1, Title = "Database Systems", Description = "Covers relational database design, SQL, normalization, indexing, and transaction management.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and has published extensively on programming pedagogy." },
            new() { Id = 4, DepartmentId = 1, Title = "Operating Systems", Description = "Exploration of process management, memory allocation, file systems, and concurrency in modern operating systems.", Credits = 4, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez specializes in algorithm design and has contributed to open-source compiler projects." },

            // Mathematics
            new() { Id = 5, DepartmentId = 2, Title = "Calculus I", Description = "Introduction to limits, derivatives, and integrals of single-variable functions with applications to science and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Carol Davis", InstructorBio = "Dr. Davis is an award-winning educator who has taught calculus for over 20 years.", IsFeatured = true },
            new() { Id = 6, DepartmentId = 2, Title = "Linear Algebra", Description = "Study of vector spaces, matrices, determinants, eigenvalues, and linear transformations.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. David Park", InstructorBio = "Dr. Park researches applied linear algebra and numerical methods." },
            new() { Id = 7, DepartmentId = 2, Title = "Probability and Statistics", Description = "Fundamentals of probability theory, random variables, distributions, hypothesis testing, and statistical inference.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:15 PM", InstructorName = "Dr. Carol Davis", InstructorBio = "Dr. Davis is an award-winning educator who has taught calculus for over 20 years." },

            // English
            new() { Id = 8, DepartmentId = 3, Title = "English Composition", Description = "Develop effective academic writing skills through essay assignments, peer review, and revision strategies.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. Emily Ward", InstructorBio = "Prof. Ward is a published author and writing workshop facilitator with a focus on clarity and voice.", IsFeatured = true },
            new() { Id = 9, DepartmentId = 3, Title = "American Literature", Description = "Survey of major works and movements in American literature from the colonial period to the present.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", InstructorName = "Prof. Frank Nguyen", InstructorBio = "Prof. Nguyen specializes in 20th-century American fiction and narrative theory." },
            new() { Id = 10, DepartmentId = 3, Title = "Creative Writing", Description = "Workshop-based course in fiction and poetry writing with emphasis on craft and peer feedback.", Credits = 3, Schedule = "Wed 6:00–8:30 PM", InstructorName = "Prof. Emily Ward", InstructorBio = "Prof. Ward is a published author and writing workshop facilitator with a focus on clarity and voice." },

            // Physics
            new() { Id = 11, DepartmentId = 4, Title = "General Physics I", Description = "Classical mechanics covering kinematics, Newton's laws, energy, momentum, and rotational motion with lab component.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Grace Kim", InstructorBio = "Dr. Kim is an experimental physicist whose research focuses on condensed matter systems.", IsFeatured = true },
            new() { Id = 12, DepartmentId = 4, Title = "Electromagnetism", Description = "Study of electric and magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 3:30–4:45 PM", InstructorName = "Dr. Henry Okafor", InstructorBio = "Dr. Okafor has published over 40 papers on electromagnetic theory and photonics." },
            new() { Id = 13, DepartmentId = 4, Title = "Quantum Mechanics", Description = "Introduction to wave-particle duality, Schrödinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. Grace Kim", InstructorBio = "Dr. Kim is an experimental physicist whose research focuses on condensed matter systems." }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(search, StringComparison.OrdinalIgnoreCase));

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

