@page "/courses"
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="courses" data-enhance>
    <div class="row mb-3">
        <div class="col-md-5">
            <input type="text" name="search" value="@Search" class="form-control" placeholder="Search courses..." />
        </div>
        <div class="col-md-4">
            <select name="departmentId" class="form-select">
                <option value="">All Departments</option>
                @foreach (var dept in CatalogService.GetDepartments())
                {
                    if (DepartmentId == dept.Id)
                    {
                        <option value="@dept.Id" selected>@dept.Name</option>
                    }
                    else
                    {
                        <option value="@dept.Id">@dept.Name</option>
                    }
                }
            </select>
        </div>
        <div class="col-md-3">
            <button type="submit" class="btn btn-primary">Filter</button>
        </div>
    </div>
</form>

@{
    var courses = CatalogService.GetCourses(Search, DepartmentId);
}

@if (courses.Any())
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Schedule</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                var dept = CatalogService.GetDepartment(course.DepartmentId);
                <tr>
                    <td><a href="courses/@course.Id">@course.Title</a></td>
                    <td>@dept?.Name</td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                </tr>
            }
        </tbody>
    </table>
}
else
{
    <p>No courses found matching your criteria.</p>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/courses/{Id:int}"
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course could not be found.</p>
}
else
{
    var dept = CatalogService.GetDepartment(course.DepartmentId);

    <PageTitle>@course.Title</PageTitle>

    <h1>@course.Title</h1>

    <dl class="row">
        <dt class="col-sm-3">Department</dt>
        <dd class="col-sm-9">@dept?.Name</dd>

        <dt class="col-sm-3">Credits</dt>
        <dd class="col-sm-9">@course.Credits</dd>

        <dt class="col-sm-3">Schedule</dt>
        <dd class="col-sm-9">@course.Schedule</dd>

        <dt class="col-sm-3">Description</dt>
        <dd class="col-sm-9">@course.Description</dd>

        <dt class="col-sm-3">Instructor</dt>
        <dd class="col-sm-9">@course.InstructorName</dd>

        <dt class="col-sm-3">Instructor Bio</dt>
        <dd class="col-sm-9">@course.InstructorBio</dd>
    </dl>

    <div class="mt-3">
        <a href="enroll" class="btn btn-success me-2">Enroll</a>
        <a href="courses" class="btn btn-secondary">Back to Courses</a>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private UniversityCourseCatalog.Models.Course? course;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Request Submitted!</h4>
        <p>Thank you, <strong>@Model.Name</strong>. Your enrollment request for the selected course has been received.</p>
    </div>
    <a href="courses" class="btn btn-primary">Browse More Courses</a>
}
else
{
    <EditForm method="post" FormName="enrollment" Model="Model" OnValidSubmit="HandleSubmit" Enhance>
        <DataAnnotationsValidator />
        <AntiforgeryToken />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="name" class="form-label">Full Name</label>
            <InputText id="name" @bind-Value="Model.Name" class="form-control" />
            <ValidationMessage For="() => Model.Name" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" />
            <ValidationMessage For="() => Model.StudentId" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                <option value="0">-- Select a Course --</option>
                @foreach (var course in CatalogService.GetCourses(null, null))
                {
                    <option value="@course.Id">@course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    private bool submitted;

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollmentRequest(Model);
        submitted = true;
    }
}

